package com.tiviloom.mobile.test;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.graphics.Rect;import android.media.AudioManager;import java.lang.reflect.*;

/** Real input gestures, output playback and branded overlays in a disposable emulator. */
public final class PremiumPlayerTest extends NativePlayerTest {
 AudioManager audio;int originalVolume;
 void full(boolean value)throws Exception{onMain(()->{host().getClass().getMethod("setFullscreen",boolean.class).invoke(host(),value);return true;});}
 void swipe(float x,float from,float to)throws Exception{View root=(View)field("root");int[] xy=new int[2];onMain(()->{root.getLocationOnScreen(xy);return true;});float px=xy[0]+root.getWidth()*x,sy=xy[1]+root.getHeight()*from,ey=xy[1]+root.getHeight()*to;long t=SystemClock.uptimeMillis();sendPointerSync(MotionEvent.obtain(t,t,0,px,sy,0));for(int i=1;i<=12;i++){SystemClock.sleep(18);sendPointerSync(MotionEvent.obtain(t,SystemClock.uptimeMillis(),2,px,sy+(ey-sy)*i/12,0));}sendPointerSync(MotionEvent.obtain(t,SystemClock.uptimeMillis(),1,px,ey,0));SystemClock.sleep(150);}
 @Override public void onStart(){try{
  activity=startActivitySync(new Intent().setClassName("com.tiviloom.mobile","com.tiviloom.mobile.NativePlaybackActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra("payload","{\"url\":\"http://10.0.2.2:18888/demo.mp4\",\"name\":\"Fixture One\",\"catalogue\":[{\"id\":\"one\",\"name\":\"Fixture One\",\"group\":\"Live TV\"},{\"id\":\"two\",\"name\":\"Fixture Two\",\"group\":\"Live TV\"}],\"history\":[\"one\"]}"));audio=(AudioManager)activity.getSystemService(Context.AUDIO_SERVICE);originalVolume=audio.getStreamVolume(AudioManager.STREAM_MUSIC);
  check("fixture displays real video",()->waitFor(()->playing()&&renderedVideo()>0));Object original=field("player");
  onMain(()->{playerCallRepeat();return true;});
  check("preview pause and center tap resume without fullscreen or reload",()->{full(false);tap("previewPause");waitFor(()->!playing());tapView((View)field("playerView"));waitFor(()->playing());require(!(boolean)field("fullscreen")&&field("player")==original,"Preview tap changed fullscreen/decoder");capture("premium-preview");});
  check("right vertical swipe adjusts volume",()->{full(true);int max=audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC);audio.setStreamVolume(AudioManager.STREAM_MUSIC,max/3,0);swipe(.85f,.58f,.28f);require(audio.getStreamVolume(AudioManager.STREAM_MUSIC)>max/3,"Volume unchanged");capture("premium-volume");int raised=audio.getStreamVolume(AudioManager.STREAM_MUSIC);swipe(.85f,.28f,.58f);require(audio.getStreamVolume(AudioManager.STREAM_MUSIC)<raised,"Down swipe did not reduce volume");});
  check("left swipe adjusts only app brightness",()->{int before=audio.getStreamVolume(AudioManager.STREAM_MUSIC);swipe(.15f,.58f,.28f);require(activity.getWindow().getAttributes().screenBrightness>0,"Brightness unchanged");require(audio.getStreamVolume(AudioManager.STREAM_MUSIC)==before,"Brightness changed volume");capture("premium-brightness");});
  check("screen lock blocks adjustment gestures",()->{tap("lockButton");int before=audio.getStreamVolume(AudioManager.STREAM_MUSIC);swipe(.85f,.58f,.28f);require(audio.getStreamVolume(AudioManager.STREAM_MUSIC)==before,"Locked swipe changed volume");tap("lockButton");});
  for(String label:new String[]{"Kanal siyahısı","Axtar","Tarixçə","Altyazı seç","Səs dilini seç","Digər funksiyalar"})check("branded bounded sheet: "+label,()->{tapLabel(label);waitFor(()->(boolean)field("dialogOpen"));android.view.accessibility.AccessibilityNodeInfo root=getUiAutomation().getRootInActiveWindow();require(root!=null&&!root.findAccessibilityNodeInfosByText("TIVILOOM").isEmpty(),"Brand header missing");Rect r=new Rect();root.getBoundsInScreen(r);require(r.left>=0&&r.top>=0&&r.right<=activity.getResources().getDisplayMetrics().widthPixels&&r.bottom<=activity.getResources().getDisplayMetrics().heightPixels,"Sheet outside viewport");capture("premium-sheet-"+label.hashCode());sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitFor(()->!(boolean)field("dialogOpen"));require(field("player")==original,"Menu replaced decoder");});

  check("Back hides keyboard before closing search and fullscreen",()->{tapLabel("Axtar");try{waitFor(()->((android.app.Dialog)field("activeDialog")).getWindow().getDecorView().hasWindowFocus());onMain(()->{android.app.Dialog d=(android.app.Dialog)field("activeDialog");android.view.View input=d.getCurrentFocus();input.requestFocus();((android.view.inputmethod.InputMethodManager)activity.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(input,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);return true;});try{waitFor(()->{android.app.Dialog d=(android.app.Dialog)field("activeDialog");return d.getWindow().getDecorView().getRootWindowInsets().isVisible(android.view.WindowInsets.Type.ime());});}catch(Throwable e){throw new AssertionError("Keyboard did not open",e);}sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);try{waitFor(()->{android.app.Dialog d=(android.app.Dialog)field("activeDialog");return (boolean)field("dialogOpen")&&!d.getWindow().getDecorView().getRootWindowInsets().isVisible(android.view.WindowInsets.Type.ime());});}catch(Throwable e){throw new AssertionError("Back did not hide keyboard before menu",e);}sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitFor(()->!(boolean)field("dialogOpen"));require((boolean)field("fullscreen"),"Keyboard/menu Back exited fullscreen");}finally{onMain(()->{android.app.Dialog d=(android.app.Dialog)field("activeDialog");if(d!=null)d.dismiss();return true;});}});
  check("leaving fullscreen restores brightness",()->{full(false);require(activity.getWindow().getAttributes().screenBrightness<0,"System brightness not restored");});
 }catch(Throwable e){failed++;report.append("FATAL ").append(e.toString());}finally{if(audio!=null)audio.setStreamVolume(AudioManager.STREAM_MUSIC,originalVolume,0);if(activity!=null)runOnMainSync(()->activity.finish());}Bundle out=new Bundle();out.putString("stream",report+"\nPASSED="+passed+" FAILED="+failed+"\n");finish(failed==0?-1:0,out);}
 void playerCallRepeat()throws Exception{Class.forName("androidx.media3.common.Player",true,activity.getClassLoader()).getMethod("setRepeatMode",int.class).invoke(field("player"),1);}
}
